"""Ground truth for the duplicate evaluation.

The dataset ships no labels, so the first question is where a trustworthy
label set comes from without hand-labelling two million pairs or grading the
model against its own output.

**The signal.** The fixture was generated by inserting each duplicate record
immediately after the record it copies, so genuine duplicate pairs have
adjacent ``Record ID`` values. This is verifiable rather than assumed: of the
294 pairs the scorer ranks at or above 0.90, *every one* has an ID gap of 1 or
2, and no pair with a distant ID reaches that score. All 136 rows carrying the
fixture's "possible duplicate" annotation have an adjacent sibling.

**Why it is not circular.** ``Record ID`` is never read by
``leadms.dedupe`` - not as a feature, not as a blocking key, not in an LLM
prompt. The labels therefore come from information the system under test
cannot see. ``tests/test_dedupe.py`` pins the no-leakage property.

**Where it stops.** ID adjacency alone is not enough: two unrelated people
can hold consecutive IDs. A pair is labelled a duplicate only if it is
adjacent *and* the identity fields agree (compatible name, same company email
domain). Pairs that are field-similar but far apart in ID are the brief's
"genuinely different people who happen to share a company and a
similar-sounding name", and are labelled negative.

This is a property of the supplied fixture and would not exist in a
production CRM; it is a way to evaluate honestly here, not a shipped feature.
"""

from __future__ import annotations

from leadms.similarity import jaro_winkler

# How far apart two Record IDs may be and still be treated as an
# insertion-adjacent pair. The observed maximum for a true duplicate is 2
# (a three-record cluster); 3 leaves a margin.
MAX_ID_GAP = 3


def _surnames_match(token_a, token_b):
    """Surnames are never abbreviated in this data, so require a close match."""
    return token_a == token_b or jaro_winkler(token_a, token_b) >= 0.92


def _given_names_compatible(tokens_a, tokens_b):
    """Compare the given-name part, allowing an initial to stand in for it.

    Written after inspecting the pairs where a first pass disagreed with the
    scorer. Two corrections came out of that review, both verifiable by eye:

    * "Jia Hui Ferrari" vs "J. Ferrari" - one person. A whole-string
      similarity test rejected this, because collapsing a two-token given
      name to a single initial changes most of the string.
    * "Ahmed Fischer" vs "Meera Fischer" - two people who happen to sit at
      consecutive Record IDs. A whole-string test accepted it, because the
      shared surname carries most of the similarity.

    Comparing the given-name and surname parts separately handles both.
    """
    given_a = [t.rstrip(".") for t in tokens_a[:-1]]
    given_b = [t.rstrip(".") for t in tokens_b[:-1]]
    if not given_a or not given_b:
        return not given_a and not given_b

    first_a, first_b = given_a[0], given_b[0]
    if first_a == first_b:
        return True
    if len(first_a) == 1:
        return first_b.startswith(first_a)
    if len(first_b) == 1:
        return first_a.startswith(first_b)
    return False


def is_duplicate_pair(a, b):
    """True when two records describe the same person, per the criteria above."""
    if abs(int(a["id"]) - int(b["id"])) > MAX_ID_GAP:
        return False

    # Identity fields must agree, otherwise consecutive IDs prove nothing.
    same_employer = bool(a.get("domain_root")) and a.get("domain_root") == b.get("domain_root")
    if not same_employer:
        return False

    tokens_a = a.get("name_tokens") or []
    tokens_b = b.get("name_tokens") or []
    if not tokens_a or not tokens_b:
        return False
    if not _surnames_match(tokens_a[-1], tokens_b[-1]):
        return False
    return _given_names_compatible(tokens_a, tokens_b)


def true_pairs(leads):
    """Every duplicate pair in the corpus, found without using the scorer.

    Scans only ID-adjacent candidates, so this is O(n * MAX_ID_GAP) and stays
    independent of the blocking strategy it is used to evaluate.
    """
    by_id = {int(lead["id"]): lead for lead in leads}
    pairs = set()
    for lead_id, lead in by_id.items():
        for offset in range(1, MAX_ID_GAP + 1):
            other = by_id.get(lead_id + offset)
            if other is not None and is_duplicate_pair(lead, other):
                pairs.add((lead_id, lead_id + offset))
    return pairs


def true_clusters(leads):
    """Duplicate pairs merged into connected components."""
    parent = {}

    def find(item):
        parent.setdefault(item, item)
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(x, y):
        root_x, root_y = find(x), find(y)
        if root_x != root_y:
            parent[root_y] = root_x

    for a, b in true_pairs(leads):
        union(a, b)

    clusters = {}
    for node in list(parent):
        clusters.setdefault(find(node), set()).add(node)
    return [sorted(members) for members in clusters.values() if len(members) > 1]
